api.look('agent');
const w = api.w, cx = w/2;
const k = api.seg(t, 0, 1);
api.path('M-60 -100 L60 -100 L60 100 L-60 100 Z', {x:cx, y:300, s:1.2, c:'fg', w:4, fill:'panel', k});
api.rect(cx-60, 215, 120, 22, {c:'accent', fill:'accent', k:api.seg(t,0.4,1)});
api.text('Checkout', cx, 380, {size:32, weight:'bold', align:'center', c:'fg', k:api.seg(t,0.5,1.2)});
api.shape('doc', cx, 480, 70, {c:'a2', k:api.seg(t,1,2), w:4});
api.arrow(cx, 520, cx, 620, {c:'accent', k:api.seg(t,1.6,2.6)});
api.say('Checkout sends an order', 0.3, 3.3);

api.look('agent');
const cx = api.w/2;
const A = api.node(cx, 190, 220, 90, 'Checkout', {icon:'phone', k:api.seg(t,0,0.8), c:'accent'});
const B = api.node(cx, 430, 240, 100, 'Payments', {icon:'gear', k:api.seg(t,0.6,1.6), c:'a3'});
api.link(A, B, {k:api.seg(t,1.2,2.4), label:'order', flow:t, c:'accent'});
api.text('Order #1042', cx, 570, {size:22, align:'center', k:api.seg(t,2.4,3.2), c:'fg'});
api.text('$48.00', cx, 605, {size:28, weight:'bold', align:'center', k:api.seg(t,2.8,3.6), c:'accent'});
api.scribble(cx, 430, 150, 70, {k:api.seg(t,3.6,5)});
api.say('Payments receives it', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
api.cam(0, api.lerp(0, -60, api.ease(api.seg(t,0,1))), 1, 0);
const B = api.node(cx, 250, 240, 100, 'Payments', {icon:'gear', c:'a3', k:1});
const K = api.node(cx, 520, 240, 100, 'Bank', {icon:'lock', c:'a2', k:api.seg(t,0.3,1.2)});
api.link(B, K, {k:api.seg(t,1,2), label:'Charge?', flow:t, c:'a2'});
api.link(K, B, {k:api.seg(t,3,4), label:'Approved', flow:t*1.2, bend:80, c:'good'});
api.shape('check', cx+140, 430, 56, {c:'good', w:6, k:api.seg(t,4,5)});
api.cam0();
api.say('The bank confirms it', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
const B = api.node(cx, 200, 240, 100, 'Payments', {icon:'gear', c:'a3', k:1});
const W = api.node(cx, 470, 240, 100, 'Warehouse', {icon:'house', c:'accent', k:api.seg(t,0.3,1.2)});
api.link(B, W, {k:api.seg(t,1,2.2), label:'Ship it', flow:t, c:'accent'});
for (let i=0;i<3;i++){
  const kk = api.stag(t, i, {gap:0.5, dur:0.7, from:2.6});
  api.box(cx-90+i*90, 600, 70, 60, {c:'fg', fill:'panel', k:kk});
  api.line(cx-90+i*90-35, 600, cx-90+i*90+35, 600, {c:'accent', k:kk});
}
api.say('Then the warehouse ships', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
const names = ['Checkout','Payments','Bank','Warehouse'];
const xs = [cx-80, cx-80, cx+80, cx-80], ys = [150, 300, 450, 600];
const N = names.map((n,i)=>api.node(xs[i], ys[i]-10, 170, 70, n, {k:api.stag(t,i,{gap:0.5,dur:0.6}), c:['accent','a3','a2','accent'][i]}));
api.link(N[0], N[1], {k:api.seg(t,2,2.8), flow:t, c:'accent'});
api.link(N[1], N[2], {k:api.seg(t,2.6,3.4), flow:t, c:'a2', bend:40});
api.link(N[2], N[3], {k:api.seg(t,3.2,4), flow:t, c:'good', bend:40});
api.brace(cx+190, 130, cx+190, 620, {k:api.seg(t,4,5)});
api.say('Order, confirm, ship', 0.4, 5.5);
